#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b) {
    return a < b ? a : b;
}
int mx(int a, int b) {
    return a > b ? a : b;
}
int read(void) {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a) {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x) {
    printf("%d ", x);
}
void emitstr(int* a, int n) {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void) {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int ans = 0, i = 0, l = 0, n = 0, r = 0, sumv = 0, t = 0;
    n = read();
    // 目标 t 只与正积分窗口和比较；先保存全部日积分。
    t = read();
    for (i = 0; i < n; i += 1) {
        a[i] = read();
    }
    l = 0;
    sumv = 0;
    // n+1 不可能是合法区间长度，用作尚未找到答案的哨兵。
    ans = (n + 1);
    for (r = 0; r < n; r += 1) {
        sumv = (sumv + a[r]);
        // 先记录达标窗口，再反复删除左端；正积分保证收缩会降低总分。
        while (sumv >= t) {
            ans = mn(ans, ((r - l) + 1));
            sumv = (sumv - a[l]);
            l = (l + 1);
        }
    }
    if (ans == (n + 1)) {
        ans = 0;
    }
    // 未找到窗口时 ans 已改为 0，否则输出最短天数。
    emit(ans);
    return 0;
}

