use std::io::{self, Read};
fn mn(a: i32, b: i32) -> i32 {
    a.min(b)
}
fn mx(a: i32, b: i32) -> i32 {
    a.max(b)
}
fn emit(x: i32) {
    print!("{} ", x);
}
fn emitstr(a: &Vec<i32>, n: i32) {
    if n == 0 {
        print!("-");
    }
    for i in 0..n {
        print!("{}", a[i as usize] as u8 as char);
    }
    print!(" ");
}
struct Reader {
    t: Vec<String>,
    p: usize,
}
impl Reader {
    fn new() -> Self {
        let mut s = String::new();
        io::stdin().read_to_string(&mut s).unwrap();
        Self {
            t: s.split_whitespace().map(String::from).collect(),
            p: 0,
        }
    }
    fn read(&mut self) -> i32 {
        let x = self.t[self.p].parse().unwrap();
        self.p += 1;
        x
    }
    fn readstr(&mut self, a: &mut Vec<i32>) -> i32 {
        let s = &self.t[self.p];
        self.p += 1;
        if s == "-" {
            return 0;
        }
        for (i, c) in s.bytes().enumerate() {
            a[i] = c as i32;
        }
        s.len() as i32
    }
}
fn main() {
    let mut reader = Reader::new();
    let mut a = vec![0i32; 20000];
    let mut b = vec![0i32; 20000];
    let mut d = vec![0i32; 20000];
    let mut e = vec![0i32; 20000];
    let mut ans: i32 = 0;
    let mut i: i32 = 0;
    let mut l: i32 = 0;
    let mut n: i32 = 0;
    let mut r: i32 = 0;
    let mut sumv: i32 = 0;
    let mut t: i32 = 0;
    n = reader.read();
    // 目标 t 只与正积分窗口和比较；先保存全部日积分。
    t = reader.read();
    i = 0;
    while i < n {
        a[(i) as usize] = reader.read();
        i += 1;
    }
    l = 0;
    sumv = 0;
    // n+1 不可能是合法区间长度，用作尚未找到答案的哨兵。
    ans = (n + 1);
    r = 0;
    while r < n {
        sumv = (sumv + a[(r) as usize]);
        // 先记录达标窗口，再反复删除左端；正积分保证收缩会降低总分。
        while (sumv >= t) {
            ans = mn(ans, ((r - l) + 1));
            sumv = (sumv - a[(l) as usize]);
            l = (l + 1);
        }
        r += 1;
    }
    if (ans == (n + 1)) {
        ans = 0;
    }
    // 未找到窗口时 ans 已改为 0，否则输出最短天数。
    emit(ans);
}
